  function instantiate(node) {
    var styles = {};
    function walk(src) {
      var out = {id:Math.random().toString(36).slice(2,10).padEnd(8,'x'),tag:src.tag};
      ['text','src','alt','href','newTab','name','collection','cls','attrs'].forEach(function(k){if(src[k]!==undefined) out[k]=JSON.parse(JSON.stringify(src[k]));});
      var s=src.s||{}, bps=s.d||s.t||s.p?s:{d:s};
      styles['n:'+out.id]=Object.assign({},JSON.parse(JSON.stringify(src.edits||{})),{s:JSON.parse(JSON.stringify(bps))});
      if(src.kids) out.kids=src.kids.map(walk);
      // Button/link labels are real tree children with their own identity,
      // so clone, delete, reusable sections and undo can handle them normally.
      if(src.tag==='a' && typeof src.text==='string') {
        var label=walk({tag:'span',text:src.text,s:{display:'inline-block'}});
        out.kids=[label].concat(out.kids||[]);delete out.text;
      }
      return out;
    }
    return {tree:walk(node),nodes:styles};
  }
